    /// should set it the same way as multicopters. Runway-landing fixed wing
    /// aircraft should set it to the opposite direction of the takeoff, assuming
    /// the takeoff happened from the threshold / touchdown zone. Units: m.
    public var approachX: Float
    /// Local Y position of the end of the approach vector. Multicopters should set
    /// this position based on their takeoff path. Grass-landing fixed wing aircraft
    /// should set it the same way as multicopters. Runway-landing fixed wing
    /// aircraft should set it to the opposite direction of the takeoff, assuming
    /// the takeoff happened from the threshold / touchdown zone. Units: m.
    public var approachY: Float
    /// Local Z position of the end of the approach vector. Multicopters should set
    /// this position based on their takeoff path. Grass-landing fixed wing aircraft
    /// should set it the same way as multicopters. Runway-landing fixed wing
    /// aircraft should set it to the opposite direction of the takeoff, assuming
    /// the takeoff happened from the threshold / touchdown zone. Units: m.
    public var approachZ: Float
    /// Timestamp (UNIX Epoch time or time since system boot). The receiving end can
    /// infer timestamp format (since 1.1.1970 or since system boot) by checking for
    /// the magnitude of the number. Units: us.
    public var timeUsec: UInt64

    public init(
        latitude: Int32 = 0,
        longitude: Int32 = 0,
        altitude: Int32 = 0,
        x: Float = 0,
        y: Float = 0,
        z: Float = 0,
        q: [Float] = Array(repeating: 0, count: 4),
        approachX: Float = 0,
        approachY: Float = 0,
        approachZ: Float = 0,
        timeUsec: UInt64 = 0
    ) {
        self.latitude = latitude
        self.longitude = longitude
        self.altitude = altitude
        self.x = x
        self.y = y
        self.z = z
        self.q = q
        self.approachX = approachX
        self.approachY = approachY
        self.approachZ = approachZ
        self.timeUsec = timeUsec
    }

    public init(from reader: PayloadReader) {
        latitude = reader.i32(at: 0)
        longitude = reader.i32(at: 4)
        altitude = reader.i32(at: 8)
        x = reader.f32(at: 12)
        y = reader.f32(at: 16)
        z = reader.f32(at: 20)
        q = (0..<4).map { reader.f32(at: 24 + $0 * 4) }
        approachX = reader.f32(at: 40)
        approachY = reader.f32(at: 44)
        approachZ = reader.f32(at: 48)
