        writer.f32(self.x, at: 12)
        writer.f32(self.y, at: 16)
        writer.f32(self.z, at: 20)
        for (i, value) in self.q.prefix(4).enumerated() { writer.f32(value, at: 24 + i * 4) }
        writer.f32(self.approachX, at: 40)
        writer.f32(self.approachY, at: 44)
