/// Battery information
public struct BatteryStatus: MavlinkMessage, Equatable {
    public static let messageId: UInt32 = 147
    public static let messageName = "BATTERY_STATUS"
    public static let crcExtra: UInt8 = 154
    /// Payload length without extensions, which is all MAVLink 1 carries.
    public static let minLength = 36
    /// Payload length with every extension field present.
    public static let maxLength = 54

    /// Consumed charge, -1: autopilot does not provide consumption estimate. Units:
    /// mAh.
    public var currentConsumed: Int32
    /// Consumed energy, -1: autopilot does not provide energy consumption estimate.
    /// Units: hJ.
    public var energyConsumed: Int32
    /// Temperature of the battery. INT16_MAX for unknown temperature. Units: cdegC.
    public var temperature: Int16
    /// Battery voltage of cells 1 to 10 (see voltages_ext for cells 11-14). Cells
    /// in this field above the valid cell count for this battery should have the
    /// UINT16_MAX value. If individual cell voltages are unknown or not measured
    /// for this battery, then the overall battery voltage should be filled in cell
    /// 0, with all others set to UINT16_MAX. If the voltage of the battery is
    /// greater than (UINT16_MAX - 1), then cell 0 should be set to (UINT16_MAX -
    /// 1), and cell 1 to the remaining voltage. This can be extended to multiple
    /// cells if the total voltage is greater than 2 * (UINT16_MAX - 1). Units: mV.
    public var voltages: [UInt16]
    /// Battery current, -1: autopilot does not measure the current. Units: cA.
    public var currentBattery: Int16
    /// Battery ID
    public var id: UInt8
    /// Function of the battery. Values from: MAV_BATTERY_FUNCTION.
    public var batteryFunction: UInt8
    /// Type (chemistry) of the battery. Values from: MAV_BATTERY_TYPE.
    public var type: UInt8
    /// Remaining battery energy. Values: [0-100], -1: autopilot does not estimate
    /// the remaining battery. Units: %.
    public var batteryRemaining: Int8
    /// Remaining battery time, 0: autopilot does not provide remaining battery time
    /// estimate. Units: s.
    public var timeRemaining: Int32
    /// State for extent of discharge, provided by autopilot for warning or external
    /// reactions. Values from: MAV_BATTERY_CHARGE_STATE.
    public var chargeState: UInt8
    /// Battery voltages for cells 11 to 14. Cells above the valid cell count for
    /// this battery should have a value of 0, where zero indicates not supported
    /// (note, this is different than for the voltages field and allows empty byte
    /// truncation). If the measured value is 0 then 1 should be sent instead.
    /// Units: mV.
    public var voltagesExt: [UInt16]
    /// Battery mode. Default (0) is that battery mode reporting is not supported or
    /// battery is in normal-use mode. Values from: MAV_BATTERY_MODE.
    public var mode: UInt8
    /// Fault/health indications. These should be set when charge_state is
    /// MAV_BATTERY_CHARGE_STATE_FAILED or MAV_BATTERY_CHARGE_STATE_UNHEALTHY (if
    /// not, fault reporting is not supported). Bitmask of: MAV_BATTERY_FAULT.
    public var faultBitmask: UInt32

    public init(
        id: UInt8 = 0,
        batteryFunction: UInt8 = 0,
        type: UInt8 = 0,
        temperature: Int16 = 0,
        voltages: [UInt16] = Array(repeating: 0, count: 10),
        currentBattery: Int16 = 0,
        currentConsumed: Int32 = 0,
        energyConsumed: Int32 = 0,
        batteryRemaining: Int8 = 0,
        timeRemaining: Int32 = 0,
        chargeState: UInt8 = 0,
        voltagesExt: [UInt16] = Array(repeating: 0, count: 4),
        mode: UInt8 = 0,
        faultBitmask: UInt32 = 0
    ) {
        self.id = id
        self.batteryFunction = batteryFunction
        self.type = type
        self.temperature = temperature
        self.voltages = voltages
        self.currentBattery = currentBattery
        self.currentConsumed = currentConsumed
        self.energyConsumed = energyConsumed
        self.batteryRemaining = batteryRemaining
        self.timeRemaining = timeRemaining
        self.chargeState = chargeState
        self.voltagesExt = voltagesExt
        self.mode = mode
        self.faultBitmask = faultBitmask
    }

    public init(from reader: PayloadReader) {
        currentConsumed = reader.i32(at: 0)
        energyConsumed = reader.i32(at: 4)
        temperature = reader.i16(at: 8)
        voltages = (0..<10).map { reader.u16(at: 10 + $0 * 2) }
        currentBattery = reader.i16(at: 30)
        id = reader.u8(at: 32)
        batteryFunction = reader.u8(at: 33)
        type = reader.u8(at: 34)
        batteryRemaining = reader.i8(at: 35)
        timeRemaining = reader.i32(at: 36)
        chargeState = reader.u8(at: 40)
        voltagesExt = (0..<4).map { reader.u16(at: 41 + $0 * 2) }
        mode = reader.u8(at: 49)
        faultBitmask = reader.u32(at: 50)
    }

    public func write(to writer: inout PayloadWriter) {
        writer.i32(self.currentConsumed, at: 0)
        writer.i32(self.energyConsumed, at: 4)
        writer.i16(self.temperature, at: 8)
        for (i, value) in self.voltages.prefix(10).enumerated() { writer.u16(value, at: 10 + i * 2) }
        writer.i16(self.currentBattery, at: 30)
        writer.u8(self.id, at: 32)
        writer.u8(self.batteryFunction, at: 33)
        writer.u8(self.type, at: 34)
        writer.i8(self.batteryRemaining, at: 35)
        writer.i32(self.timeRemaining, at: 36)
        writer.u8(self.chargeState, at: 40)
        for (i, value) in self.voltagesExt.prefix(4).enumerated() { writer.u16(value, at: 41 + i * 2) }
        writer.u8(self.mode, at: 49)
        writer.u32(self.faultBitmask, at: 50)
    }
