public struct DistanceSensor: MavlinkMessage, Equatable {
    public static let messageId: UInt32 = 132
    public static let messageName = "DISTANCE_SENSOR"
    public static let crcExtra: UInt8 = 85
    /// Payload length without extensions, which is all MAVLink 1 carries.
    public static let minLength = 14
    /// Payload length with every extension field present.
    public static let maxLength = 39

    /// Timestamp (time since system boot). Units: ms.
    public var timeBootMs: UInt32
    /// Minimum distance the sensor can measure. Units: cm.
    public var minDistance: UInt16
    /// Maximum distance the sensor can measure. Units: cm.
    public var maxDistance: UInt16
    /// Current distance reading. Units: cm.
    public var currentDistance: UInt16
    /// Type of distance sensor. Values from: MAV_DISTANCE_SENSOR.
    public var type: UInt8
    /// Onboard ID of the sensor
    public var id: UInt8
    /// Direction the sensor faces. downward-facing: ROTATION_PITCH_270,
    /// upward-facing: ROTATION_PITCH_90, backward-facing: ROTATION_PITCH_180,
    /// forward-facing: ROTATION_NONE, left-facing: ROTATION_YAW_90, right-facing:
    /// ROTATION_YAW_270. Values from: MAV_SENSOR_ORIENTATION.
    public var orientation: UInt8
    /// Measurement variance. Max standard deviation is 6cm. UINT8_MAX if unknown.
    /// Units: cm^2.
    public var covariance: UInt8
    /// Horizontal Field of View (angle) where the distance measurement is valid and
    /// the field of view is known. Otherwise this is set to 0. Units: rad.
    public var horizontalFov: Float
    /// Vertical Field of View (angle) where the distance measurement is valid and
    /// the field of view is known. Otherwise this is set to 0. Units: rad.
    public var verticalFov: Float
    /// Quaternion of the sensor orientation in vehicle body frame (w, x, y, z
    /// order, zero-rotation is 1, 0, 0, 0). Zero-rotation is along the vehicle body
    /// x-axis. This field is required if the orientation is set to
    /// MAV_SENSOR_ROTATION_CUSTOM. Set it to 0 if invalid."
    public var quaternion: [Float]
    /// Signal quality of the sensor. Specific to each sensor type, representing the
    /// relation of the signal strength with the target reflectivity, distance, size
    /// or aspect, but normalised as a percentage. 0 = unknown/unset signal quality,
    /// 1 = invalid signal, 100 = perfect signal. Units: %.
    public var signalQuality: UInt8

    public init(
        timeBootMs: UInt32 = 0,
        minDistance: UInt16 = 0,
        maxDistance: UInt16 = 0,
        currentDistance: UInt16 = 0,
        type: UInt8 = 0,
        id: UInt8 = 0,
        orientation: UInt8 = 0,
        covariance: UInt8 = 0,
        horizontalFov: Float = 0,
        verticalFov: Float = 0,
        quaternion: [Float] = Array(repeating: 0, count: 4),
        signalQuality: UInt8 = 0
    ) {
        self.timeBootMs = timeBootMs
        self.minDistance = minDistance
        self.maxDistance = maxDistance
        self.currentDistance = currentDistance
        self.type = type
        self.id = id
        self.orientation = orientation
        self.covariance = covariance
        self.horizontalFov = horizontalFov
        self.verticalFov = verticalFov
        self.quaternion = quaternion
        self.signalQuality = signalQuality
    }

    public init(from reader: PayloadReader) {
        timeBootMs = reader.u32(at: 0)
        minDistance = reader.u16(at: 4)
        maxDistance = reader.u16(at: 6)
        currentDistance = reader.u16(at: 8)
        type = reader.u8(at: 10)
        id = reader.u8(at: 11)
        orientation = reader.u8(at: 12)
        covariance = reader.u8(at: 13)
        horizontalFov = reader.f32(at: 14)
        verticalFov = reader.f32(at: 18)
        quaternion = (0..<4).map { reader.f32(at: 22 + $0 * 4) }
        signalQuality = reader.u8(at: 38)
    }

    public func write(to writer: inout PayloadWriter) {
        writer.u32(self.timeBootMs, at: 0)
        writer.u16(self.minDistance, at: 4)
        writer.u16(self.maxDistance, at: 6)
        writer.u16(self.currentDistance, at: 8)
        writer.u8(self.type, at: 10)
        writer.u8(self.id, at: 11)
        writer.u8(self.orientation, at: 12)
        writer.u8(self.covariance, at: 13)
        writer.f32(self.horizontalFov, at: 14)
        writer.f32(self.verticalFov, at: 18)
        for (i, value) in self.quaternion.prefix(4).enumerated() { writer.f32(value, at: 22 + i * 4) }
        writer.u8(self.signalQuality, at: 38)
    }
}

